ALTER TABLE public.videos ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN duration_seconds double precision, ADD COLUMN size_bytes bigint;
ALTER TABLE public.videos ADD CONSTRAINT videos_upload_description_length CHECK (char_length(description) <= 2000), ADD CONSTRAINT videos_upload_duration CHECK (duration_seconds IS NULL OR (duration_seconds > 0 AND duration_seconds <= 1200)), ADD CONSTRAINT videos_upload_size CHECK (size_bytes IS NULL OR (size_bytes > 0 AND size_bytes <= 104857600));
CREATE OR REPLACE FUNCTION public.validate_video_title() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF (TG_OP = 'INSERT' OR NEW.title IS DISTINCT FROM OLD.title) AND (char_length(btrim(NEW.title)) < 1 OR char_length(NEW.title) > 200) THEN RAISE EXCEPTION 'Title must be between 1 and 200 characters'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_video_title BEFORE INSERT OR UPDATE ON public.videos FOR EACH ROW EXECUTE FUNCTION public.validate_video_title();